const main = async () => {
    try {
        // 加载环境变量
        loadEnv();
        // 获取任务ID参数
        const taskId = process.argv[2];
        if (!taskId) {
            console.error('错误: 缺少任务ID参数');
            console.error('用法: npx ts-node examples/check-video-task.ts <任务ID>');
            return;
        }
        // 获取API密钥
        const accessKey = process.env.JIMENG_ACCESS_KEY;
        const secretKey = process.env.JIMENG_SECRET_KEY;
        if (!accessKey || !secretKey) {
            console.error('错误: 缺少API密钥。请设置JIMENG_ACCESS_KEY和JIMENG_SECRET_KEY环境变量。');
            return;
        }
        // 创建客户端
        const client = new jimeng_client_1.JimengClient({
            accessKey,
            secretKey,
            debug: true // 打开调试模式
        });
        console.log('=== 即梦AI视频任务查询 ===');
        console.log(`正在查询任务: ${taskId}`);
        // 获取任务结果
        const resultResponse = await client.getVideoResult({
            task_id: taskId
        });
        // 显示任务状态
        console.log('\n任务状态:', resultResponse.status || '未知');
        if (resultResponse.status === "SUCCEED" && resultResponse.video_urls && resultResponse.video_urls.length > 0) {
            // 任务成功完成
            console.log('\n✓ 视频生成成功!');
            console.log('\n生成的视频链接:');
            resultResponse.video_urls.forEach((url, index) => {
                console.log(`${index + 1}. ${url}`);
            });
        }
        else if (resultResponse.status === "RUNNING") {
            // 任务仍在进行中
            console.log('\n任务仍在处理中，请稍后再次查询');
            console.log('重新检查命令: npx ts-node examples/check-video-task.ts ' + taskId);
        }
        else {
            // 任务失败或其他状态
            console.error('\n视频生成未成功:', resultResponse.error);
        }
    }
    catch (error) {
        console.error('发生错误:', error);
    }
};
// 运行主函数
main();
